function CommonTipsBoardRewardPreview:RefreshBoardByRewards(rewards, text, isDrawing, isShowArrow)
	self.rewards = rewards
	if not isNull(isDrawing) then
		self.isDrawing = checkBool(isDrawing)
	end
	if isShowArrow then
		KTool.SetActive(self.Arrow.gameObject, true)
	else
		KTool.SetActive(self.Arrow.gameObject, false)
	end
	if text then
		CfUtils.FillText(self.TitleText, text)
	else
		CfUtils.FillText(self.TitleText, localize("奖励预览"))
	end
	---@type SuperScrollView.LoopStaggeredGridView
	--local gridView = self.GridView
	--if rewards then
	--	GameUtils.ReloadData(gridView, #rewards)
	--end
	--gridView:SetListItemCount(50)
	self:FillRewards()
end

function CommonTipsBoardRewardPreview:FillRewards()
	if not self.rewards then
		return
	end

	for k, v in pairs(self.rewards) do
		local go = CfUtils.InstantiateGo(self.GoodNode, self.View)
		self:FillReward(go, v)
	end
	local count = table.count(self.rewards)
	if count < 4 then
		--local ViewRt = KTool.GetComponent(self.View.gameObject, typeof(CS.UnityEngine.RectTransform))
		--local RewardsRt = KTool.GetComponent(self.Rewards.gameObject, typeof(CS.UnityEngine.RectTransform))
		--
