		--ViewRt.sizeDelta = Vector2.New(count * 120, 162)
	else
		self.Rewards.enabled = true
		-- self.View.enabled = true
	end
end

function CommonTipsBoardRewardPreview:FillReward(go, data)
	if not go or not data then
		return
	end

	local goodNode = go.transform:Find("GoodNode")
	local getImageTrans = goodNode.transform:Find("getimg")
	local reScale = goodNode.gameObject:GetComponent(typeof(ReverseScale))
	reScale:ResetScale()
	
	local goodItemNodeMB = GetLuaBehaviour(goodNode.gameObject, GoodNodeMBPath)
	if not isNull(goodItemNodeMB) then
		if isNull(goodItemNodeMB.Env) then
			goodItemNodeMB:Init()
		end
		---@type GoodNodeMB
		local goodItemNodeEnv = goodItemNodeMB.Env
		local goodsNum = 0
		if isSet(data, 'num') then
			goodsNum = data.num
		elseif isSet(data, 'goodsNum') then
			goodsNum = data.goodsNum
		end
		
		local numText
		if checkNumber(goodsNum) > 0 then
			numText = 'x' .. FormatCurrencyNum(goodsNum)
		end
		
		goodItemNodeEnv:Reload({
			goodsId = data.goodsId, isShowNo = true, text = numText
		})
		
		KTool.SetActive(getImageTrans.gameObject, self.isDrawing)
		goodItemNodeEnv:SetClickButtonAction(function(goodsId)
			local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
			if isTable(vo) then
				GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id)
			end
		end)
		
		-- 显示获取概率
		local showProbability = false
		local weight = 1
		if isSet(data, 'weight') then
			weight = data.weight / 100
			showProbability = true
		end
		if showProbability then
			local probabilityRoot = go.transform:Find("Probability")
			KTool.SetActive(probabilityRoot.gameObject, showProbability)
			local txt = probabilityRoot:Find("TextNumber"):GetComponent(typeof(CS.TMPro.TextMeshProUGUI))
			txt.text = tostring(weight) .. '%'
		end
	end
	KTool.SetActive(go, true)
end

